171		var existing int64
172		err = tx.QueryRow(
173			`SELECT cursor FROM snapshot_versions WHERE document_id = ? AND name = ?`,
174			documentID, name,
175		).Scan(&existing)
176		switch {
177		case errors.Is(err, sql.ErrNoRows):
178			return VersionResult{}, ErrVersionNotFound
179		case err != nil:
180			return VersionResult{}, err
