199	// DeleteSnapshotVersion hard-deletes one version marker of documentID. The
200	// gate (404/403) is taken first; a name without a marker is
201	// ErrVersionNotFound. The snapshot is left untouched; once the marker commits
202	// the name is free to bind again.
203	func (s *Service) DeleteSnapshotVersion(documentID, deviceID, name string) error {
204		tx, err := s.db.Begin()
205		if err != nil {
206			return err
207		}
208		defer func() { _ = tx.Rollback() }()
