233	// RestoreSnapshotVersion resolves a version name of documentID to its
234	// snapshot and appends that snapshot's state as one ordinary change, with
235	// exactly the semantics of RestoreSnapshot: the gate is taken first in the
236	// transaction, a missing marker yields ErrVersionNotFound and a missing
237	// snapshot ErrSnapshotNotFound, after which the shared restore path decides
238	// idempotency and conflict (an id occupied by an ordinary change is 409). The
239	// document cursor advances by one on a genuinely new restore and the long
240	// polls and subscribers are woken.
241	func (s *Service) RestoreSnapshotVersion(documentID, deviceID, changeID, name string) (RestoreResult, error) {
